import pickle
import os
import json
from datetime import datetime

class ModeleManager:
    def __init__(self, repertoire='modeles'):
        self.repertoire = repertoire
        os.makedirs(repertoire, exist_ok=True)
        self.metadonnees_file = os.path.join(repertoire, 'metadonnees.json')
        self.metadonnees = self._charger_metadonnees()

    def _charger_metadonnees(self):
        if os.path.exists(self.metadonnees_file):
            with open(self.metadonnees_file, 'r') as f:
                return json.load(f)
        return {'versions': []}

    def _sauvegarder_metadonnees(self):
        with open(self.metadonnees_file, 'w') as f:
            json.dump(self.metadonnees, f, indent=2)

    def sauvegarder(self, modele, nom, metadonnees_extra=None):
        version = len(self.metadonnees['versions']) + 1
        date = datetime.now().isoformat()
        nom_fichier = f"{nom}_v{version}_{date.replace(':', '-')}.pkl"
        chemin = os.path.join(self.repertoire, nom_fichier)

        with open(chemin, 'wb') as f:
            pickle.dump(modele, f)

        metadonnees = {
            'version': version,
            'nom': nom,
            'date': date,
            'fichier': nom_fichier,
            'metadonnees': metadonnees_extra or {}
        }
        self.metadonnees['versions'].append(metadonnees)
        self._sauvegarder_metadonnees()
        return version

    def charger(self, nom, version=None):
        if version is None:
            # Charger la dernière version
            versions = [v for v in self.metadonnees['versions'] if v['nom'] == nom]
            if not versions:
                raise ValueError(f"Aucun modèle trouvé pour {nom}")
            version_info = sorted(versions, key=lambda x: x['version'])[-1]
        else:
            version_info = next(
                (v for v in self.metadonnees['versions'] 
                 if v['nom'] == nom and v['version'] == version),
                None
            )
            if version_info is None:
                raise ValueError(f"Version {version} du modèle {nom} non trouvée")

        chemin = os.path.join(self.repertoire, version_info['fichier'])
        with open(chemin, 'rb') as f:
            return pickle.load(f)

    def lister_modeles(self):
        return [{'nom': v['nom'], 'version': v['version'], 'date': v['date']} 
                for v in self.metadonnees['versions']]
