import csv

def filtrer_et_sauvegarder(enregistrements, seuil, nom_fichier):
    filtres = [e for e in enregistrements if e['aqi'] > seuil]

    with open(nom_fichier, 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['timestamp', 'temperature', 'humidite', 'aqi'])
        writer.writeheader()
        for enreg in filtres:
            writer.writerow({
                'timestamp': enreg['timestamp'].isoformat(),
                'temperature': enreg['temperature'],
                'humidite': enreg['humidite'],
                'aqi': enreg['aqi']
            })
    return len(filtres)
