def iterateur_enregistrements(nom_fichier):
    taille = 14
    with open(nom_fichier, 'rb') as f:
        while True:
            data = f.read(taille)
            if len(data) < taille:
                break
            timestamp, temperature, humidite, aqi = struct.unpack('iffH', data)
            yield {
                'timestamp': datetime.fromtimestamp(timestamp),
                'temperature': temperature,
                'humidite': humidite,
                'aqi': aqi
            }

# Utilisation
for enreg in iterateur_enregistrements('capteurs.bin'):
    print(enreg['timestamp'], enreg['temperature'])
