import pickle
import gzip
import lzma
import bz2
import os
from contextlib import contextmanager

class PickleCompressManager:
    def __init__(self, repertoire='data', niveau_compression=6):
        self.repertoire = repertoire
        self.niveau_compression = niveau_compression
        os.makedirs(repertoire, exist_ok=True)
        self.methodes = {
            'gzip': gzip.open,
            'lzma': lzma.open,
            'bz2': bz2.open
        }

    def sauvegarder(self, objet, nom, methode='gzip'):
        if methode not in self.methodes:
            raise ValueError(f"Méthode {methode} non supportée")

        extension = 'pkl' if methode is None else f'pkl.{methode}'
        chemin = os.path.join(self.repertoire, f"{nom}.{extension}")

        if methode is None:
            with open(chemin, 'wb') as f:
                pickle.dump(objet, f, protocol=pickle.HIGHEST_PROTOCOL)
        else:
            with self.methodes[methode](chemin, 'wb', compresslevel=self.niveau_compression) as f:
                pickle.dump(objet, f, protocol=pickle.HIGHEST_PROTOCOL)

        return chemin

    def charger(self, nom, methode='gzip'):
        extensions = ['pkl', 'pkl.gzip', 'pkl.lzma', 'pkl.bz2']

        if methode is not None:
            extension = f'pkl.{methode}'
            chemin = os.path.join(self.repertoire, f"{nom}.{extension}")
            if os.path.exists(chemin):
                with self.methodes[methode](chemin, 'rb') as f:
                    return pickle.load(f)

        # Essayer toutes les méthodes si non spécifiée
        for ext in extensions:
            chemin = os.path.join(self.repertoire, f"{nom}.{ext}")
            if os.path.exists(chemin):
                if ext == 'pkl':
                    with open(chemin, 'rb') as f:
                        return pickle.load(f)
                else:
                    methode = ext.split('.')[1]
                    with self.methodes[methode](chemin, 'rb') as f:
                        return pickle.load(f)

        raise FileNotFoundError(f"Aucun fichier trouvé pour {nom}")

    @contextmanager
    def charger_en_continu(self, nom, methode='gzip'):
        """Permet de charger un objet en streaming pour les gros fichiers."""
        extension = f'pkl.{methode}'
        chemin = os.path.join(self.repertoire, f"{nom}.{extension}")
        if not os.path.exists(chemin):
            raise FileNotFoundError(f"Fichier {chemin} non trouvé")

        with self.methodes[methode](chemin, 'rb') as f:
            # Lecture par lots
            while True:
                try:
                    yield pickle.load(f)
                except EOFError:
                    break

    def supprimer(self, nom):
        extensions = ['pkl', 'pkl.gzip', 'pkl.lzma', 'pkl.bz2']
        supprimes = []
        for ext in extensions:
            chemin = os.path.join(self.repertoire, f"{nom}.{ext}")
            if os.path.exists(chemin):
                os.remove(chemin)
                supprimes.append(chemin)
        return supprimes

# Exemple d'utilisation
manager = PickleCompressManager('donnees_compressees')
donnees = [{"id": i, "valeur": i*2} for i in range(100000)]

# Sauvegarde avec gzip
chemin = manager.sauvegarder(donnees, 'test_data', 'gzip')
print(f"Sauvegardé dans : {chemin}")

# Chargement
donnees_chargees = manager.charger('test_data', 'gzip')
print(f"Nombre d'éléments chargés : {len(donnees_chargees)}")
